function findTopic(text) {
    const t = text.toLowerCase(); let best = null, score = 0;
    for (const k in TOPICS) { const s = TOPICS[k].words.filter(w => t.includes(w)).length; if (s > score) { score = s; best = k; } }
    return best;
}
// ===== Live AI (Gemini API). Paste your key to turn it on =====
const GEMINI_API_KEY = "";               // get a free key from Google AI Studio
const GEMINI_MODEL = "gemini-2.5-flash"; // change if Google renames the model
const history = [];
let busy = false;
const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
$("mode").textContent = GEMINI_API_KEY
    ? "Live AI is on. Answers use only the college information in this site."
    : "Demo mode: replies come from sample college data. Add a Gemini API key in the code to turn on live AI.";

function sysPrompt() {
    return "You are the Student Assistant for Inmantec College. Answer ONLY from the college information below. " +
        "Reply in the same language the student writes in (English, Hindi or Hinglish). Keep answers short and friendly. " +
        "If the answer is not in the information, say you do not know and ask them to contact the college office. " +
        "Never invent dates, fees or rules.\n\nCOLLEGE INFORMATION:\n" + Object.values(TOPICS).map(t => t.a).join("\n\n");
}
async function liveReply(text) {
    history.push({ role: "user", parts: [{ text }] });
    try {
        const r = await fetch("http://10.10.50.88:11445/api/generate \)");
        if (!r.ok) throw new Error("HTTP " + r.status);
        const d = await r.json();
        const out = (d.candidates?.[0]?.content?.parts || []).map(p => p.text || "").join("");
        if (!out) throw new Error("empty reply");
        history.push({ role: "model", parts: [{ text: out }] });
        return out;
    } catch (e) { history.pop(); throw e; }
}
function localReply(text) {
    const k = findTopic(text) || Object.keys(TOPICS).find(x => TOPICS[x].q === text);
    return k ? TOPICS[k].a : "I do not have a verified answer for that yet. Please contact the " + OFFICE + " or raise a complaint below.";
}

async function callModel() {
    let userQuery = document.getElementById("q").value;
    const response = await fetch('http://10.10.50.88:11445/api/generate', {
        method: "POST",
        headers: {
            "Content-Type": "application/json",
        },
        body: JSON.stringify({
            model: "inmantec_model:latest",
            prompt: userQuery,
            stream: false
        })
    })

    const data = await response.json();
    console.log(data.response)
}

function addMsg(kind, text) {
    const row = document.createElement("div"); row.className = "msg " + kind;
    if (kind === "bot") { const av = document.createElement("div"); av.className = "av"; av.textContent = "IC"; row.appendChild(av); }
    const b = document.createElement("div"); b.className = "bub"; if (text) b.textContent = text;
    row.appendChild(b); $("thread").appendChild(row); $("thread").scrollTop = $("thread").scrollHeight;
    return b;
}
async function stream(el, text) {
    el.textContent = "";
    for (const w of text.split(/(\s+)/)) {
        el.textContent += w; $("thread").scrollTop = $("thread").scrollHeight;
        if (!reduced) await new Promise(r => setTimeout(r, 22));
    }
}
async function ask(text) {
    text = text.trim(); if (!text || busy) return;
    busy = true; $("thread").classList.add("show"); $("q").value = "";
    addMsg("user", text);
    const bub = addMsg("bot"); bub.innerHTML = '<span class="dots"><span></span><span></span><span></span></span>';
    let reply;
    try {
        if (GEMINI_API_KEY) reply = await liveReply(text);
        else { await new Promise(r => setTimeout(r, 600)); reply = localReply(text); }
    } catch (e) { reply = "Live AI could nobe reached, so here is the saved answer.\n\n" + localReply(text); }
    await stream(bub, reply);
    busy = false;
}

