const f = { name: $("cName"), id: $("cId"), cat: $("cCat"), to: $("cTo"), sub: $("cSub"), msg: $("cMsg"), anon: $("cAnon") };
let toTouched = false;
function preview() {
    const an = f.anon.checked;
    $("pName").textContent = an ? "Anonymous" : (f.name.value || "Not entered");
    $("pId").textContent = an ? "Hidden" : (f.id.value || "Not entered");
    $("pCat").textContent = f.cat.value || "Not selected";
    $("pSub").textContent = f.sub.value || "Not entered";
    $("pTo").textContent = f.to.value || "Not selected";
}
f.cat.addEventListener("change", () => { if (!toTouched && ROUTE[f.cat.value]) f.to.value = ROUTE[f.cat.value]; preview(); });
f.to.addEventListener("change", () => { toTouched = true; preview(); });
f.anon.addEventListener("change", () => { f.name.disabled = f.id.disabled = f.anon.checked; preview(); });
[f.name, f.id, f.sub, f.msg].forEach(el => el.addEventListener("input", preview));

$("submit").onclick = () => {
    const err = $("err"); err.textContent = "";
    if (!f.anon.checked && (!f.name.value.trim() || !f.id.value.trim())) { err.textContent = "Enter your name and student ID, or tick anonymous."; return; }
    if (!f.cat.value || !f.to.value) { err.textContent = "Select a category and who to send it to."; return; }
    if (!f.sub.value.trim() || f.msg.value.trim().length < 10) { err.textContent = "Add a subject and a message of at least 10 characters."; return; }
    const id = "CMP-" + new Date().getFullYear() + "-" + Math.floor(1000 + Math.random() * 9000);
    // Firebase: complaint ko online database mein save karo (agar connect ho)
    if (window.saveComplaint) window.saveComplaint({
        complaintId: id,
        anonymous: f.anon.checked,
        studentName: f.anon.checked ? "" : f.name.value.trim(),
        studentId: f.anon.checked ? "" : f.id.value.trim(),
        category: f.cat.value,
        subject: f.sub.value.trim(),
        message: f.msg.value.trim(),
        sendTo: f.to.value
    });
    const r = $("ready"); r.className = "ready ok";
    r.innerHTML = "<span>Complaint submitted. Your complaint ID is</span><b></b><span></span>";
    r.children[1].textContent = id;
    r.children[2].textContent = "Sent to: " + f.to.value + ". Status tracking comes in the next version.";
};
preview();
// ===== Mic: bolke sawal poochna =====
const micBtn = document.getElementById("mic");
const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
if (!SR) {
    micBtn.style.display = "none";
} else {
    const rec = new SR();
    rec.lang = "en-IN";
    rec.interimResults = false;
    micBtn.addEventListener("click", () => {
        if (micBtn.classList.contains("on")) { rec.stop(); return; }
        rec.start();
        micBtn.classList.add("on");
    });
    rec.onresult = (e) => { ask(e.results[0][0].transcript); };
    rec.onend = () => micBtn.classList.remove("on");
    rec.onerror = (e) => {
        micBtn.classList.remove("on");
        if (e.error === "network") {
            document.getElementById("mode").textContent = "Mic ke liye internet chahiye. Abhi type karke poochiye.";
            document.getElementById("mode").style.display = "block";
        }
    };
}

