(function () {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const upcoming = EVENTS
        .map(e => ({ ...e, d: new Date(e.date + "T00:00:00"), short: e.title.replace(/\s*\(sample\)/i, "") }))
        .filter(e => e.d >= today)
        .sort((a, b) => a.d - b.d);

    const fmt = e => e.d.getDate() + " " + e.d.toLocaleString("en-IN", { month: "short" });
    const full = e => e.short + "\n- Date: " + fmt(e) + ", " + e.time + "\n- Venue: " + e.venue + "\n- About: " + e.desc + "\n- Details: " + e.details;

    // ----- Events ka section banao -----
    const sec = document.createElement("section");
    sec.className = "panel";
    sec.id = "events";

    const head = document.createElement("div");
    head.className = "ph";
    head.innerHTML = "<div><h2>Upcoming College Events</h2><p>Click an event to ask the assistant about it.</p></div>";

    const grid = document.createElement("div");
    grid.className = "ev-grid";
    if (!upcoming.length) {
        grid.innerHTML = '<p class="ev-empty">No upcoming events right now. Please check back soon.</p>';
    }

    upcoming.forEach(e => {
        const card = document.createElement("div");
        card.className = "ev-card";
        card.setAttribute("role", "button");
        card.tabIndex = 0;

        const date = document.createElement("div");
        date.className = "ev-date";
        date.innerHTML = "<b></b><span></span>";
        date.children[0].textContent = e.d.getDate();
        date.children[1].textContent = e.d.toLocaleString("en-IN", { month: "short" });

        const info = document.createElement("div");
        info.innerHTML = '<strong></strong><small></small><p></p><span class="ev-more">Ask about this event \u203a</span>';
        info.children[0].textContent = e.title;
        info.children[1].textContent = e.time + " | " + e.venue;
        info.children[2].textContent = e.desc;

        const open = () => {
            ask("Tell me about " + e.short);
            $("ask").scrollIntoView({ behavior: "smooth", block: "start" });
        };
        card.addEventListener("click", open);
        card.addEventListener("keydown", ev => {
            if (ev.key === "Enter" || ev.key === " ") { ev.preventDefault(); open(); }
        });

        card.append(date, info);
        grid.appendChild(card);
    });
    sec.append(head, grid);
    document.getElementById("complaint").before(sec);

    // ----- Chat ko events ki jaankari do -----
    if (typeof TOPICS !== "undefined" && TOPICS.events) {
        TOPICS.events.a = upcoming.length
            ? "Upcoming College Events\n" + upcoming.map(e => "- " + e.short + ": " + fmt(e) + ", " + e.time + ", " + e.venue).join("\n")
            : "There are no upcoming events right now. Please check the notice board.";
    }
    // Live AI (Gemini) ko har event ki poori detail milti hai
    TOPICS.eventdetails = { label: "Event Details", q: "", words: [], a: upcoming.map(full).join("\n\n") };

    // Demo mode: kisi event ka naam likhne ya card dabane par uski detail dikhao
    const oldLocalReply = localReply;
    localReply = function (text) {
        const t = text.toLowerCase();
        let best = null, bestScore = 0;
        upcoming.forEach(e => {
            const words = e.short.toLowerCase().split(" ").filter(w => w.length > 3);
            let score = words.filter(w => t.includes(w)).length;
            if (t.includes(e.short.toLowerCase())) score += 5;
            if (score >= 2 && score > bestScore) { best = e; bestScore = score; }
        });
        return best ? full(best) : oldLocalReply(text);
    };
})();
// ===== Robot: hilta hai, likhta hai aur bolta hai =====
(function () {
    const robot = document.querySelector(".hero .bot");
    const hero = document.querySelector(".hero");
    // Yahan apni marzi se greeting badal sakte ho
    const GREETING = "Hello! My name is Inmantec College Student Assistant. How can I help you today?";
    const SPOKEN = "Hello! My name is Inmantec College Student Assistant. Ask me about attendance, exams, fees, scholarships, events and placements.";
    const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;

    const bubble = document.createElement("div");
    bubble.className = "robot-bubble";
    bubble.innerHTML = '<span class="rb-text"></span><small>Tap the robot to hear me</small>';
    hero.appendChild(bubble);
    const textEl = bubble.querySelector(".rb-text");

    robot.setAttribute("role", "button");
    robot.tabIndex = 0;
    robot.setAttribute("aria-label", "Hear the assistant introduce itself");

    let typingId = 0;
    async function typeText(t) {
        const id = ++typingId;
        textEl.textContent = "";
        if (reducedMotion) { textEl.textContent = t; return; }
        for (const ch of t) {
            if (id !== typingId) return;
            textEl.textContent += ch;
            await new Promise(r => setTimeout(r, 28));
        }
    }

    function speak() {
        robot.classList.add("talking");
        typeText(GREETING);
        const stop = () => robot.classList.remove("talking");
        setTimeout(stop, 12000);
        if (!("speechSynthesis" in window)) { setTimeout(stop, 3500); return; }
        speechSynthesis.cancel();
        const u = new SpeechSynthesisUtterance(SPOKEN);
        u.lang = "en-IN";
        u.rate = 0.95;
        u.pitch = 1.05;
        const voices = speechSynthesis.getVoices();
        const v = voices.find(x => x.lang === "en-IN") || voices.find(x => x.lang.startsWith("en"));
        if (v) u.voice = v;
        u.onend = stop;
        u.onerror = e => { if (e.error !== "interrupted" && e.error !== "canceled") stop(); };
        speechSynthesis.speak(u);
    }

    robot.addEventListener("click", speak);
    robot.addEventListener("keydown", e => {
        if (e.key === "Enter" || e.key === " ") { e.preventDefault(); speak(); }
    });
    typeText(GREETING);   // page khulte hi greeting likha dikhega
})();
// ===== Search box: sawal apne aap ek-ek karke type hote hain =====
(function () {
    const input = document.getElementById("q");
    // Naya sawal dikhana ho to neeche list mein ek line jod do
    const LONG_QUESTIONS = [
        "Can you help me with attendance check?",
        "Can you help me with fee related problem?",
        "When are the exams and results?",
        "What scholarships are available?",
        "Can you share the class timetable?",
        "What are the library timings?",
        "What events are coming up?",
        "How does placement work?",
        "Meri hazri kam hai to kya karein?"
    ];
    const SHORT_QUESTIONS = [
        "Attendance check?",
        "Fee problem?",
        "Exam dates?",
        "Scholarships?",
        "Class timetable?",
        "Library timings?",
        "Upcoming events?",
        "Placement info?",
        "Meri hazri kam hai?"
    ];
    // Phone par chhote sawal, laptop par poore sawal
    const QUESTIONS = window.innerWidth <= 560 ? SHORT_QUESTIONS : LONG_QUESTIONS;
    const IDLE_TEXT = "Type your question here...";
    const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
    let qi = 0, ci = 0, deleting = false;

    function tick() {
        // Student type kar raha ho ya box khula ho to animation ruki rahe
        if (document.activeElement === input || input.value) { setTimeout(tick, 500); return; }

        const full = QUESTIONS[qi];
        if (reduced) {                       // kam motion wale users ke liye: bas badalta rahe
            input.placeholder = full;
            qi = (qi + 1) % QUESTIONS.length;
            setTimeout(tick, 3000);
            return;
        }
        if (!deleting) {
            ci++;
            input.placeholder = full.slice(0, ci) + "|";
            if (ci === full.length) { deleting = true; input.placeholder = full; setTimeout(tick, 1800); return; }
            setTimeout(tick, 55);
        } else {
            ci--;
            input.placeholder = full.slice(0, ci) + "|";
            if (ci === 0) { deleting = false; qi = (qi + 1) % QUESTIONS.length; setTimeout(tick, 350); return; }
            setTimeout(tick, 25);
        }
    }
    input.addEventListener("focus", () => { input.placeholder = IDLE_TEXT; });
    input.addEventListener("blur", () => { ci = 0; deleting = false; });
    tick();
})();

